const g = k => (dv[k] == null ? "" : String(dv[k])).trim();
const problems = [];
for (const k of ["first_name","last_name","company_name","selected_time"]) {
  if (!g(k)) problems.push({field: k, issue: "missing"});
}
if (!/^\+[1-9]\d{6,14}$/.test(g("callback_number"))) problems.push({field: "callback_number", issue: "not E.164"});
if (["America/New_York","America/Chicago","America/Denver","America/Los_Angeles","America/Phoenix"].indexOf(g("prospect_timezone")) < 0)
  problems.push({field: "prospect_timezone", issue: "not IANA"});
if (g("booking_uid").length < 6) problems.push({field: "booking_uid", issue: "calendar did not return an id"});
return { valid: problems.length === 0, problems };
